import json
from pathlib import Path
H = json.loads(Path("input/_headings.json").read_text(encoding="utf-8"))
src = Path("input/大数据研究中心可研.raw.txt")
lines = src.read_text(encoding="utf-8").split("\n")
errs = []
for ln, lvl, title in H:
    actual = lines[ln].strip()
    if actual != title:
        errs.append({"line": ln, "want": title, "got": actual})
if errs:
    print("MISMATCH:", json.dumps(errs, ensure_ascii=False, indent=2)); raise SystemExit(1)
out = []
for i, l in enumerate(lines):
    out.append(l)
head_by_line = {ln: (lvl, t) for ln, lvl, t in H}
res, cur = [], None
for i, l in enumerate(lines):
    if i in head_by_line:
        lvl, title = head_by_line[i]
        if title == "总论":
            res.append("# 前端与目录")
            res.append("")
            res.append("## 封面与编制信息")
            res.append("")
        if title == "目录":
            res.append("## 目录")
            res.append("")
        res.append("#" * lvl + " " + title)
    else:
        res.append(l)
text = "\n".join(res)
Path("input/大数据研究中心可研.md").write_text(text, encoding="utf-8")
print("headings inserted:", len(H), "chars:", len(text), "lines:", len(res))
# 预览前 40 行非空
n = 0
for l in res:
    if l.strip() and n < 25:
        print(repr(l[:70])); n += 1

