    .replace(/<br\s*\/?>/gi,"\n").replace(/<\/(p|div|tr|li|h[1-6]|table)>/gi,"\n").replace(/<\/(td|th)>/gi," | ")
    .replace(/<[^>]+>/g," ").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&ldquo;|&rdquo;/g,'"')
    .replace(/[ \t\u00a0]+/g," ").replace(/\n{2,}/g,"\n").trim();
}
async function grab(url: string, file: string, kw?: RegExp) {
  try { const r = await tools.web_fetch({ url }); const t = stripHtml(((r.body as any).content || ""));
    await tools.write({ file_path: file, content: t });
    let idx = 0; if (kw) { const m = kw.exec(t); idx = m ? Math.max(0, (m.index||0) - 500) : 0; }
    return { url, ok: true, len: t.length, ex: t.slice(idx, idx + 1800) };
  } catch (e: any) { return { url, ok: false, err: String(e.message || e).slice(0, 110) }; }
}
