def corpus_get_skeleton(corpus_dir, section=None):
    """从 section_templates 取节模板。

    section 支持三种写法（依次尝试）：
      1) 完整文件名/词干，如 "32-项目建设内容及规模"
      2) 序号，如 "32" 或 "S032"（对应文件名前缀 NN-）
      3) 标题片段，如 "项目建设内容及规模"
