    dirs = [p for p in props if p.endswith("_dir") or p.endswith("_root") or p == "path"]
    print(f"{name:28s} required={req}  目录类参数={dirs}")
PY`, description: "List tool params", timeoutMs: 60000 }),
]);
console.log("=== groups.py ===\n" + R(a));
console.log("=== 工具入参 ===\n" + R(b));", "description": "List MCP tool parameters by group"}

