{"code": "const K = "/Users/apple/Desktop/workdsh/knowledge/knowledge-processing-expert";
const py = `# -*- coding: utf-8 -*-
import json, subprocess, sys
K = ${JSON.stringify(K)}
groups = ["processing", "assembly", "library", "semantic", "reserved"]
for g in groups:
    frames = [
        {"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18"}},
        {"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}},
    ]
    inp = "\\n".join(json.dumps(f) for f in frames) + "\\n"
    p = subprocess.run([f"{K}/.venv/bin/python", f"{K}/mcp/servers/kp_{g}_server.py"],
                       input=inp, capture_output=True, text=True, timeout=120)
    tools = []
    for line in p.stdout.splitlines():
        try: o = json.loads(line)
        except Exception: continue
        if o.get("id") == 2:
            tools = o["result"]["tools"]
    print(f"=== kp-{g} ({len(tools)} 工具) ===")
    for t in tools:
        sch = t.get("inputSchema") or {}
        props = list((sch.get("properties") or {}).keys())
        req = sch.get("required") or []
        dirs = [x for x in props if x.endswith("_dir") or x.endswith("_root") or x in ("path", "corpus_dir")]
        if dirs or len(props) <= 3:
            print(f"  {t['name']:26s} required={str(req):38s} props={props}")
    print()
`;
await tools.write({ file_path: "kabuild/_probe_groups.py", content: py });
const r = await tools.bash({ command: `cd '${K}' && .venv/bin/python '${process.env.PWD || ""}' 2>/dev/null; .venv/bin/python "/Users/apple/workdsh/.test-runtime/preview/workdsh-projects/1667349c74609b4500654ac978662087a947e3f197112fe62706d819b8d081f0/kabuild/_probe_groups.py"`, description: "Probe tool schemas per group", timeoutMs: 300000 });
console.log(r.kind === "foreground" ? r.stdout.text + r.stderr.text : JSON.stringify(r));", "description": "Probe tool schemas per group"}

