{"code": "function stripHtml(h: string) {
  return h.replace(/<script[\s\S]*?<\/script>/gi," ").replace(/<style[\s\S]*?<\/style>/gi," ")
    .replace(/<br\s*\/?>/gi,"\n").replace(/<\/(p|div|tr|li|h[1-6]|table)>/gi,"\n")
    .replace(/<[^>]+>/g," ").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&quot;/g,'"')
    .replace(/&#x27;|&#39;/g,"'").replace(/[ \t\u00a0]+/g," ").replace(/\n{2,}/g,"\n").trim();
}
try {
  const r = await tools.web_fetch({ url: "https://docs.getsemantica.ai/modules/" });
  const raw = ((r.body as any).content || "");
  await tools.write({ file_path: "references/raw/semantica-modules-原文.html", content: raw });
  const t = stripHtml(raw);
  await tools.write({ file_path: "references/raw/semantica-modules.txt", content: t });
  console.log("status", r.statusCode, "| raw", raw.length, "| text", t.length);
  console.log(t.slice(0, 5000));
  const links = Array.from(raw.matchAll(/href="([^"]+)"/g)).map(m => m[1]).filter(u => u.includes("module") || u.startsWith("/")).slice(0, 40);
  console.log("\n=== 链接 ===");
  console.log([...new Set(links)].join("\n"));
} catch (e: any) { console.log("FAIL:", String(e.message || e).slice(0, 300)); }", "description": "Fetch Semantica modules documentation"}

