{"code": "const WS = "/Users/apple/workdsh/.test-runtime/preview/workdsh-projects/1667349c74609b4500654ac978662087a947e3f197112fe62706d819b8d081f0";
const PKG = WS + "/知识资产-上财大数据研究中心可研";
const raw = await tools.bash({ command: `cat '${PKG}/外部核验/dedup-review.yaml'`, description: "Read dedup review", timeoutMs: 60000 });
const rev = JSON.parse(raw.kind === "foreground" ? raw.stdout.text : "{}");
const names: string[] = [];
for (const e of rev.entries) { names.push(e.a); names.push(e.b); }
const uniq = [...new Set(names)];
const out: string[] = [];
let alias = 0, nv = 0, md = 0, err = 0;
for (const n of uniq.slice(0, 34)) {
  try {
    const r: any = await tools["mcp__kp-semantic__semantic_classify"]({ name: n } as any);
    const t = r?.content?.[0]?.text ?? JSON.stringify(r);
    const k = JSON.parse(t);
    if (k.kind === "alias_of_existing") alias++; else if (k.kind === "new_variable") nv++; else md++;
    out.push(`${k.kind.padEnd(18)} ${n}${k.concept_id ? "  → " + k.concept_id : ""}`);
  } catch (e: any) { err++; out.push("ERR " + n + " " + String(e.message || e).slice(0, 60)); }
}
console.log(out.join("\n"));
console.log(`\n统计：alias_of_existing ${alias} | new_variable ${nv} | metadata ${md} | 错误 ${err}  （共 ${uniq.length} 个主体名）`);", "description": "Test semantic_classify baseline on subject names"}

