def anchor(t):
    """在 import 段之后插入（放在 'import json...' 或第一个 from import 之后）。"""
    lines = t.split("\n")
    for i, l in enumerate(lines[:30]):
        if l.startswith("import ") or (l.startswith("from ") and "import" in l):
            last = i
            for j in range(i + 1, min(i + 20, len(lines))):
                if lines[j].startswith(("import ", "from ")) and "import" in lines[j]:
                    last = j
                elif lines[j].strip() == "" or lines[j].startswith(("API", "print", "#")):
                    break
            return "\n".join(lines[:last + 1]) + "\n" + INJECT + "\n".join(lines[last + 1:])
    return INJECT + t

for name in ("semantica_judge_bulk.py", "semantica_judge_test.py", "semantica_llm_probe.py"):
