    if "from semantica_env import load_env" in t:
        print("  已含共享载入:", name); continue
    t2 = anchor(t)
    t2 = t2.replace('API = os.environ.get("DEEPSEEK_API_KEY")', 'API = os.environ["DEEPSEEK_API_KEY"]')
    p.write_text(t2, encoding="utf-8")
    print("  已注入共享载入:", name)

