    return "\n".join(out)

def insert_pos(t: str) -> int:
    tree = ast.parse(t)
    for node in tree.body:
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            continue
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
            continue
        return node.lineno - 1
    return len(t.split("\n"))

for name in ("semantica_judge_bulk.py", "semantica_judge_test.py", "semantica_llm_probe.py", "semantica_p0b_crosscheck.py"):
    p = K / name
    t = strip_inject(p.read_text(encoding="utf-8"))
    lines = t.split("\n")
    k = insert_pos(t)
    new = "\n".join(lines[:k]) + ("\n" if k else "") + INJECT + "\n".join(lines[k:])
    ast.parse(new)
    p.write_text(new, encoding="utf-8")
    print("  %-32s 注入于第 %d 行" % (name, k + 1))

