import json
K = Path("${WS}/kabuild")
OUT = Path("${WS}/知识资产-上财大数据研究中心可研/外部核验")
NL = chr(10)

HOOK = (NL + NL + "try:" + NL +
        "    _sys.path.insert(0, str(_Path(__file__).resolve().parent))" + NL +
        "    from semantica_metrics import append_history as _append_history" + NL +
        "    _append_history(str(OUT), \"KIND\", {})" + NL +
        "except Exception:" + NL + "    pass" + NL)

for name, kind in (("semantica_rule_judge.py", "rule"), ("semantica_judge_test.py", "llm")):
    p = K / name
    t = p.read_text(encoding="utf-8")
    if "semantica_metrics" in t:
        print("  已有历史钩子，跳过:", name); continue
    hook = (NL + NL + "try:" + NL +
            "    from semantica_metrics import append_history as _append_history" + NL +
            "    _append_history(str(OUT), " + repr(kind) + ", {\"accuracy\": locals().get(\"acc\") or (ok / len(detail) if 'detail' in dir() and detail else None), \"n\": len(detail) if 'detail' in dir() else None})" + NL +
            "except Exception:" + NL + "    pass" + NL)
