      {"kind": "rule", "date": "2026-10-13", "at": "2026-10-13T22:30:00", "accuracy": 0.882, "n": 17,
       "note": "规则判官为确定性，多轮应一致"},
    ]}, ensure_ascii=False, indent=2), encoding="utf-8")
    print("  已回填 judge-accuracy-history.yaml（3 条）")
else:
    print("  历史文件已存在")
`;
