"""诊断：A 组的"未复现"到底是真漏还是匹配失败；B 组候选是真漏抽还是 LLM 噪声。"""
import json, os, random
from pathlib import Path
PKG = Path(os.environ["KP_CORPUS_DIR"])
OUT = PKG / "外部核验"
nodes = json.loads((PKG / "graph/nodes.yaml").read_text(encoding="utf-8"))
