A = [r for r in recs if r["group"] == "A"]
res = json.loads((OUT / "p0b-crosscheck.yaml").read_text(encoding="utf-8"))
missed = res["A_precision_proxy"]["missed_sample"]

print("### A 组「未复现」样例：我方事实 vs 同 chunk 的三元组\n")
by_chunk = {r["chunk"]: r for r in A}
for m in missed[:3]:
    cid = m["chunk"]
    print("chunk", cid, "| 我方事实:", m["subject"], "=", m["value"], m["unit"])
    ts = by_chunk.get(cid, {}).get("triplets", [])[:6]
    for t in ts:
        print("     Semantica:", t["subject"], "|", t["predicate"], "|", t["object"])
    print()

print("### B 组 38 条「候选漏抽」全览\n")
for c in res["B_recall_proxy"]["candidates"][:38]:
    print("  [%s] %s | %s | %s" % (c["chunk"], c["subject"][:22], c["predicate"][:18], c["object"][:40]))
`;
